  description="All type in screens goes through this component (screens may not set font properties). as = element (h1, h2, p, span...); tone = default, muted, accent, brand, signature, on-brand.">
<style>
.t { margin: 0; color: var(--color-ink); font-family: var(--font-family-body); text-wrap: pretty; }
.t--display-xl, .t--display-lg, .t--display-md, .t--display-sm { font-family: var(--font-family-display); font-weight: var(--font-weight-display); line-height: var(--font-leading-display); letter-spacing: var(--font-tracking-display); text-wrap: balance; }
.t--display-xl { font-size: var(--font-size-display-xl); }
.t--display-lg { font-size: var(--font-size-display-lg); }
.t--display-md { font-size: var(--font-size-display-md); }
.t--display-sm { font-size: var(--font-size-display-sm); }
.t--title { font: var(--font-weight-semibold) var(--font-size-xl) / var(--font-leading-snug) var(--font-family-body); letter-spacing: var(--font-tracking-tight); text-wrap: balance; }
.t--subtitle { font: var(--font-weight-medium) var(--font-size-lg) / var(--font-leading-snug) var(--font-family-body); }
.t--body { font: var(--font-weight-regular) var(--font-size-md) / var(--font-leading-body) var(--font-family-body); }
.t--body-sm { font: var(--font-weight-regular) var(--font-size-sm) / var(--font-leading-body) var(--font-family-body); }
.t--caption { font: var(--font-weight-regular) var(--font-size-xs) / var(--font-leading-snug) var(--font-family-body); color: var(--color-muted); }
.t--eyebrow { font: var(--font-eyebrow-weight) var(--font-eyebrow-size) / 1.3 var(--font-family-body); letter-spacing: var(--font-eyebrow-tracking); text-transform: var(--font-eyebrow-case); color: var(--color-accent-text); }
.t--mono { font: var(--font-weight-medium) var(--font-size-sm) / 1.4 var(--font-family-mono); letter-spacing: var(--font-tracking-wide); }
.t--tone-muted { color: var(--color-muted); }
.t--tone-accent { color: var(--color-accent-text); }
.t--tone-brand { color: var(--color-brand); }
.t--tone-signature { color: var(--color-signature); }
.t--tone-on-brand { color: var(--color-on-brand); }
</style>
<template>
<{{as}} class="t t--{{variant}} t--tone-{{tone}}"><dfw-slot></dfw-slot></{{as}}>
</template>
